CREATE OR REPLACE FUNCTION public.ensure_chapter_row(
  p_chapter_id uuid,
  p_module_id uuid,
  p_title text,
  p_description text,
  p_order_index integer,
  p_module_title text DEFAULT 'Module',
  p_module_description text DEFAULT '',
  p_cefr text DEFAULT 'A1',
  p_module_order integer DEFAULT 1
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  VALUES (p_module_id, COALESCE(NULLIF(p_module_title, ''), 'Module'), COALESCE(p_module_description, ''), COALESCE(NULLIF(p_cefr, ''), 'A1'), COALESCE(p_module_order, 1))
  ON CONFLICT (id) DO NOTHING;

  VALUES (p_chapter_id, p_module_id, COALESCE(NULLIF(p_title, ''), 'Lesson'), COALESCE(p_description, ''), COALESCE(p_order_index, 1), ARRAY[]::text[], 0, '{}'::jsonb)
  ON CONFLICT (id) DO NOTHING;
END;
$$;

GRANT EXECUTE ON FUNCTION public.ensure_chapter_row(uuid, uuid, text, text, integer, text, text, text, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_chapter_row(uuid, uuid, text, text, integer, text, text, text, integer) TO anon;
